        // given
        int[] prices = {90, 100};

        // when
        int[] spans = stockSpan.calculateSpans(prices);

        // then
        assertEquals(1, spans[0]);
        assertEquals(2, spans[1]);
    }

    @Test
    public void calculateSpans_EmptyArray_ReturnsCorrectArray() {
        // given
        int[] prices = {};

        // when
        int[] spans = stockSpan.calculateSpans(prices);

        // then
        assertNull(spans);
    }
}
